        pub fn acknowledge_event_status(&mut self, snapshot: event_status::Snapshot) {
            let kept = self.0.read::<0x64>() & !event_status::FIELDS;
            self.0.write::<0x64>(kept | snapshot.0);
        }

        /// Read `RX_STATUS`.
        #[inline]
