    pub struct LpWdt<P: oer_mmio::Placement = oer_mmio::Fixed<0x20801000>>(
        oer_mmio::Block<P, LpWdtWords>,
    );

    /// The words [`LpWdt`] holds, as byte offsets from its instance's base.
    pub struct LpWdtWords;

    impl oer_mmio::Registers for LpWdtWords {
        type Sharing = oer_mmio::sharing::Owned;
        const WORDS: &'static [usize] = &[0x0, 0x4, 0x14, 0x18];
    }

    impl oer_mmio::Words for LpWdtWords {
        const OWNED: &'static [usize] = &[0x0, 0x4, 0x14, 0x18];
        const OBSERVED: &'static [usize] = &[];
    }

    /// The part's device registers, as the PAC root claims them.
    pub type LpWdtClaim = oer_mmio::Block<oer_mmio::Fixed<0x20801000>, LpWdtWords>;

    impl LpWdt {
        /// The owner of the part's device registers.
        #[inline]
        pub fn new(block: LpWdtClaim) -> Self {
            Self(block)
        }
    }

    impl<'a> LpWdt<oer_mmio::Host<'a>> {
        /// The part over host memory, for tests of its accessors.
        pub fn host(words: &'a mut [u32]) -> Result<Self, oer_mmio::HostTooSmall> {
            oer_mmio::Block::host(words).map(Self)
        }
    }

    impl<P: oer_mmio::Placement> LpWdt<P> {
        /// Read `CONFIG0`.
        #[inline]
        pub fn read_config0(&self) -> config0::R {
            config0::R(self.0.read::<0x0>())
        }

        /// Read `CONFIG0`, change fields and write it back; every other bit keeps
        /// the value read, every write-trigger field is zero.
        #[inline]
        pub fn modify_config0(&mut self, change: impl FnOnce(&mut config0::W)) {
            let mut value = config0::W(self.0.read::<0x0>());
            change(&mut value);
            self.0.write::<0x0>(value.0);
        }

        /// Read `CONFIG1`.
        #[inline]
        pub fn read_config1(&self) -> config1::R {
            config1::R(self.0.read::<0x4>())
        }

        /// Read `CONFIG1`, change fields and write it back; every other bit keeps
        /// the value read, every write-trigger field is zero.
        #[inline]
        pub fn modify_config1(&mut self, change: impl FnOnce(&mut config1::W)) {
            let mut value = config1::W(self.0.read::<0x4>());
            change(&mut value);
            self.0.write::<0x4>(value.0);
        }

        /// Write to the write-trigger field `FEED` of `FEED`, starting its
        /// hardware action once; every other bit is zero or its fixed value.
        #[inline]
        pub fn trigger_feed_feed(&mut self) {
            self.0.write::<0x14>(0x80000000);
        }

        /// Read `WPROTECT`.
        #[inline]
        pub fn read_wprotect(&self) -> wprotect::R {
            wprotect::R(self.0.read::<0x18>())
        }

        /// Read `WPROTECT`, change fields and write it back; every other bit keeps
        /// the value read, every write-trigger field is zero.
        #[inline]
        pub fn modify_wprotect(&mut self, change: impl FnOnce(&mut wprotect::W)) {
            let mut value = wprotect::W(self.0.read::<0x18>());
            change(&mut value);
            self.0.write::<0x18>(value.0);
        }
    }

