    /// A request the profile routes: its original code is kept apart from
    /// the byte it reaches, including an alias on another host.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub struct Request {
        route: Route,
        index: u8,
    }

    impl Request {
        /// The request `code` for byte `index`, if the profile routes it.
        pub const fn new(profile: Profile, code: u8, index: u8) -> Option<Self> {
            match route(profile, code) {
                Some(route) => Some(Self { route, index }),
                None => None,
            }
        }

        /// The request reaching `address` under its own command code.
        pub const fn from_address(profile: Profile, address: Address) -> Option<Self> {
            match route(profile, address.block()) {
                Some(route) if route.command_code == address.block() => Some(Self {
                    route,
                    index: address.index(),
                }),
                _ => None,
            }
        }

        /// The request's route, with its original request code.
        pub const fn route(self) -> Route {
            self.route
        }

        /// The byte the request reaches.
        pub const fn address(self) -> Address {
            self.route().address(self.index)
        }

        /// The byte's index in its block.
        pub const fn index(self) -> u8 {
            self.index
        }
    }

